def fast_ls(seq: List[int]) -> List[int]:
    """Fast 2-opt, 1-relocate, and best-efficiency insertion for multi-start trials."""
    improved = True
    while improved:
        improved = False
        sc, tend = eval_seq(seq)
        for i in range(len(seq)):
            for j in range(i + 2, len(seq) + 1):
                cand = seq[:i] + seq[i:j][::-1] + seq[j:]
                csc, ctend = eval_seq(cand)
                if csc > sc + 1e-7:
                    seq, sc, tend = cand, csc, ctend
                    improved = True
        for i in range(len(seq)):
            u = seq[i]
            rem = seq[:i] + seq[i + 1 :]
            for j in range(len(rem) + 1):
                if j == i:
                    continue
                cand = rem[:j] + [u] + rem[j:]
                csc, ctend = eval_seq(cand)
                if csc > sc + 1e-7:
                    seq, sc, tend = cand, csc, ctend
                    improved = True
                    break
            if improved:
                break
        if improved:
            continue
        used = set(seq)
        best_cand = None
        best_eff = 0.0
        for u in avail:
            if u in used:
                continue
            for j in range(len(seq) + 1):
                cand = seq[:j] + [u] + seq[j:]
                csc, ctend = eval_seq(cand)
                if csc > sc + 1e-7:
                    d_sc = round(csc - sc, 4)
                    d_t = max(0.5, ctend - tend)
                    eff = d_sc / d_t
                    if eff > best_eff:
                        best_eff = eff
                        best_cand = cand
        if best_cand is not None:
            seq = best_cand
            improved = True
    return seq

