    """Full VND including Or-opt, 4-window permutations, and relocating swaps."""
    seq = fast_ls(seq)
    improved = True
    while improved:
        improved = False
        sc, tend = eval_seq(seq)
        for i in range(max(0, len(seq) - 3)):
            w = seq[i : i + 4]
