                    csc, ctend = eval_seq(cand)
                    if csc > sc + 1e-7:
                        seq, sc, tend = cand, csc, ctend
                        improved = True
                        break
                if improved:
                    break
            if improved:
                break
        if improved:
            seq = fast_ls(seq)
            continue
        used = set(seq)
        best_swap = None
