def ingest_packets(self, packets: List[Dict[str, Any]], tools_map_fn: Optional[Any] = None) -> None:
    need_replan = False
    discovery_found = False
    for pkt in sorted(packets, key=lambda p: int(p["tick"])):
        tk = int(pkt["tick"])
        if tk in self.processed_ticks:
            continue
        self.processed_ticks.add(tk)
        prev_sampled_count = len(self.sampled_ids)
        for sid in pkt.get("sampled_targets", []):
            self.sampled_ids.add(sid)
        if len(self.sampled_ids) > prev_sampled_count:
            need_replan = True

        exec_cmd = self.commands_by_exec_tick.get(tk)
        stop_occ, disc_occ = self.estimator.process_telemetry(pkt, exec_cmd)
        if disc_occ:
            discovery_found = True
        if stop_occ:
            print(f"  [WARN] Safety stop detected at state_tick={tk}! Clearing in-flight queue.", flush=True)
            for future_tk in list(self.commands_by_exec_tick.keys()):
                if future_tk > tk:
                    self.commands_by_exec_tick[future_tk] = {"action": "wait"}
            self.current_goal_node = None
            self.waypoints = []
            need_replan = True

    if discovery_found and tools_map_fn is not None:
        new_map = tools_map_fn()
        if self.planner.sync_targets(new_map["targets"], self.estimator.slip_est):
            print(
                f"  [INFO] Synced new discoveries; total known targets = {len(self.planner.targets)}",
                flush=True,
            )
            need_replan = True

    # Periodically refresh travel matrix with learned slip parameters
    for refresh_tk in (45, 130, 230):
        if self.estimator.last_tick >= refresh_tk and refresh_tk not in self.slip_refreshed_at:
            self.slip_refreshed_at.add(refresh_tk)
            self.planner.refresh_for_slip(self.estimator.slip_est)
            need_replan = True

    if need_replan and not self.returning_to_base:
        self._replan_from_predicted_state()

def predict_state_before_tick(self, exec_tick: int) -> Tuple[float, float, float, Set[str]]:
    """Propagate state from latest telemetry tick up to (exec_tick - 1)."""
    px = self.estimator.x
    py = self.estimator.y
    pbatt = self.estimator.battery
    vsampled = set(self.sampled_ids)

    for tau in range(self.estimator.last_tick + 1, exec_tick):
        charge = self.estimator.expected_solar_charge(tau)
        pbatt = min(100.0, pbatt + charge) - float(self.rules["idle_cost"])
        cmd = self.commands_by_exec_tick.get(tau)
        if cmd is None or cmd["action"] == "wait":
            continue
        elif cmd["action"] == "sample":
            pbatt -= float(self.rules["sample_cost"])
            # Credit nearest active unsampled target within target_radius
            best_id = None
            best_d = float(self.rules["target_radius"])
            for t in self.planner.targets:
                tid = t["id"]
                if tid in vsampled:
                    continue
                if int(t.get("appear_tick", 0)) > tau:
                    continue
                d = math.hypot(float(t["x"]) - px, float(t["y"]) - py)
                if d <= best_d:
                    best_d = d
                    best_id = tid
            if best_id is not None:
                vsampled.add(best_id)
        elif cmd["action"] == "drive":
            h = float(cmd["heading_deg"]) + self.estimator.bias
            m = float(cmd["metres"])
            res = drive(self.surf, self.physics, px, py, h, m, self.estimator.slip_est, noise=0.0)
            px, py = res["x"], res["y"]
            pbatt -= res["energy"]
            if res["stop"] is not None:
                # Subsequent queued commands would be cleared
                break

    return px, py, pbatt, vsampled

def _replan_from_predicted_state(self) -> None:
    next_exec = max(self.estimator.last_tick + self.delay_ticks + 1, self.last_reserved_tick + 1)
    px, py, _, vsampled = self.predict_state_before_tick(next_exec)
    self.tour = [u for u in self.tour if self.planner.targets[u - 1]["id"] not in vsampled]
    new_tour = self.planner.optimize_tour(
        px,
        py,
        float(next_exec - 1),
        vsampled,
        self.estimator.slip_est,
        max_return_tick=409.0,
        seed_seq=self.tour,
